<?php defined('BASEPATH') or exit('No direct script access allowed');
$company_page_title='Tarefas da empresa';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_tasks'.$q);$labels=['todo'=>'A fazer','in_progress'=>'Em andamento','done'=>'Concluída'];
$hidden=function($action)use($esc,$company_tasks_csrf,$request_key,$task){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_tasks_csrf" value="'.$esc($company_tasks_csrf).'"><input type="hidden" name="request_key" value="'.$esc($request_key).'">';if($task)echo '<input type="hidden" name="task_id" value="'.(int)$task['id'].'"><input type="hidden" name="revision" value="'.(int)$task['revision'].'">';};
?>
<section class="company-settings-card"><h1>Tarefas da empresa</h1><?php if($error){ ?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><?php } ?>
<?php if(!$project){ ?><p>Abra um projeto para listar ou criar tarefas.</p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_projects')); ?>">Abrir projetos</a><?php }else{ ?>
<h2>Projeto: <?= $esc($project['name']); ?></h2><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_projects?project='.(int)$project['id'])); ?>">Voltar ao projeto</a>
<?php if($task){ ?><?php if($can_create){ ?><p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_task_copies?kind=project&source='.(int)$task['id'])); ?>">Revisar nova cópia privada desta tarefa</a></p><?php }else{ ?><p>Copiar uma tarefa exige permissão atual para criar tarefas nesta empresa.</p><?php } ?><h3><?= $esc($task['name']); ?> — <?= $esc($labels[$task['status']]); ?></h3><p><?= nl2br($esc($task['description'])); ?></p><p>Prazo <?= $esc($task['due_date']); ?></p><p>Prioridade: <?= $esc(CompanyTaskPriority::labels()[(int)($task['priority']??2)]); ?></p>
<p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_project_extras?kind=task&id='.(int)$task['id'])); ?>">Dependências, seguidores e anexos da tarefa</a></p>
<?php if($task['checklist']){ ?><h4>Checklist</h4><ul><?php foreach($task['checklist'] as $item){ ?><li><?= $item['done']?'Concluído: ':'Pendente: '; ?><?= $esc($item['text']); ?></li><?php } ?></ul><?php } ?>
<?php $contactCommentNames=[];foreach(($task_authorship['comments']??[]) as $source)$contactCommentNames[(int)$source['comment_id']]=$source['author_name'];if(is_array($task_authorship??null)){require APPPATH.'views/admin/companies/project_task_authorship.php';}if((int)$task['assignee_id']===0){ ?><p>Aguardando atribuição de responsável.</p><?php } ?><h4>Comentários</h4><?php foreach($task['comments'] as $comment){ ?><article><p><?= nl2br($esc($comment['body'])); ?></p><small><?= $esc($comment['created_at']); ?> · <?= (int)$comment['actor_id']>0?'Funcionário #'.(int)$comment['actor_id']:$esc(isset($contactCommentNames[(int)($comment['id']??0)])?'Contato: '.$contactCommentNames[(int)$comment['id']]:'Origem de contato indisponível'); ?></small></article><?php } ?>
<p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_time_billing?project='.(int)$task['project_id'])); ?>">Consultar lotes e horas restantes</a></p>
<p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_task_billing?task='.(int)$task['id'])); ?>">Revisar faturamento da tarefa</a></p><h4>Tempo registrado</h4><ul><?php $own_running=false;foreach($task['timers'] as $timer){if((int)$timer['actor_id']===$actor&&$timer['stopped_at']===null)$own_running=true; ?><li>Funcionário #<?= (int)$timer['actor_id']; ?> · <?= $esc($timer['started_at']); ?> · <?= $timer['stopped_at']===null?'Em execução':$esc($timer['seconds'].' segundos (encerrado em '.$timer['stopped_at'].')'); ?></li><?php } ?></ul>
<?php if($can_edit&&$project['status']==='active'&&$task['status']!=='done'&&!in_array($task['billing_state']??'none',['converting','converted'],true)){ ?>
<?= form_open($url());$hidden('comment'); ?><label for="task-comment">Adicionar comentário</label><textarea id="task-comment" class="form-control" name="comment" maxlength="4000" required></textarea><button type="submit">Registrar comentário</button><?= form_close(); ?>
<?= form_open($url());$hidden($own_running?'stop':'start'); ?><p>Um cronômetro pode ficar ativo por funcionário. O tempo é medido no servidor; nenhum faturamento é gerado.</p><button type="submit"><?= $own_running?'Parar meu cronômetro':'Iniciar meu cronômetro'; ?></button><?= form_close(); ?>
<?php } ?>
<?php if($can_edit&&$project['status']==='active'&&!in_array($task['billing_state']??'none',['converting','converted'],true)){ ?><h4>Editar tarefa</h4><?= form_open($url());$hidden('update'); ?><input type="hidden" name="task[project_id]" value="<?= (int)$project['id']; ?>"><?php $values=$task;$form_id='task-edit';require APPPATH.'views/admin/companies/tasks_fields.php'; ?><label for="task-status">Estado</label><select id="task-status" class="form-control" name="task[status]"><?php foreach($labels as $state=>$label){ ?><option value="<?= $esc($state); ?>" <?= $task['status']===$state?'selected':''; ?>><?= $esc($label); ?></option><?php } ?></select><p>Para concluir, marque todo o checklist e pare todos os cronômetros. Uma tarefa concluída pode ser reaberta enquanto o projeto estiver ativo.</p><button type="submit">Salvar tarefa</button><?= form_close(); ?><?php } ?><?php } ?>
<h3>Lista de tarefas do projeto</h3><div class="table-responsive"><table class="table"><thead><tr><th>Tarefa</th><th>Prazo</th><th>Estado</th><th>Prioridade</th></tr></thead><tbody><?php foreach($directory['items'] as $row){ ?><tr><td><a href="<?= $esc($url('?task='.(int)$row['id'])); ?>"><?= $esc($row['name']); ?></a></td><td><?= $esc($row['due_date']); ?></td><td><?= $esc($labels[$row['status']]); ?></td><td><?= $esc(CompanyTaskPriority::labels()[(int)($row['priority']??2)]); ?></td></tr><?php } ?></tbody></table></div><?php if($directory['next']!==null){ ?><a href="<?= $esc($url('?project='.(int)$project['id'].'&after='.$directory['next'])); ?>">Próxima página</a><?php } ?>
<?php if($can_create&&$project['status']==='active'){ ?><h3>Nova tarefa</h3><?= form_open($url());$hidden('create'); ?><input type="hidden" name="task[project_id]" value="<?= (int)$project['id']; ?>"><?php $values=['priority'=>(int)($creation_options['default_task_priority']??'2'),'name'=>'','description'=>'','assignee_id'=>($creation_defaults['new_task_auto_assign_current_member']??'1')==='1'?$actor:0,'due_date'=>$project['due_date'],'checklist'=>[]];$form_id='task-new';require APPPATH.'views/admin/companies/tasks_fields.php'; ?><label for="task-new-status">Estado inicial</label><select id="task-new-status" class="form-control" name="task[status]"><?php foreach(['todo'=>'A fazer','in_progress'=>'Em andamento']as$state=>$label){?><option value="<?= $esc($state); ?>" <?= ($creation_defaults['default_task_status']??'todo')===$state?'selected':''; ?>><?= $esc($label); ?></option><?php }?></select><button type="submit">Criar tarefa</button><?= form_close(); ?><?php } ?>
<?php } ?></section><?php require APPPATH.'views/admin/companies/layout_tail.php'; ?>
